'use strict';

// MODULES //

var expit = require( '@stdlib/math/base/special/expit' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var NINF = require( '@stdlib/constants/float64/ninf' );


// MAIN //

/**
* Evaluates the Gaussian Error Linear Unit (GELU) activation function using a quick 1.702 approximation.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = quick( 0.0 );
* // returns 0.0
*
* @example
* var v = quick( 1.0 );
* // returns ~0.8458
*
* @example
* var v = quick( -Infinity );
* // returns -0.0
*
* @example
* var v = quick( Infinity );
* // returns Infinity
*
* @example
* var v = quick( NaN );
* // returns NaN
*/
function quick( x ) {
	if ( isnan( x ) ) {
		return NaN;
	}
	if ( x === NINF ) {
		return -0.0;
	}
	return x * expit( 1.702 * x );
}


// EXPORTS //

module.exports = quick;
